package typescript

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	"github.com/masagroup/soft.gen/v2/internal/engine/goldentest"
	"github.com/masagroup/soft.gen/v2/internal/writer"
)

// The first line of a file generated by v1 and by v2.
const (
	v1Header = "// Code generated by soft.generator.ts. DO NOT EDIT."
	v2Header = "// Code generated by soft-gen ts. DO NOT EDIT."
)

// toolsEnv names a directory whose node_modules resolve prettier and oxlint
// (soft.ts/ecore): the tests formatting TypeScript are skipped without it.
const toolsEnv = "SOFT_GEN_TS_TOOLS"

// formatDir formats the .ts files of dir as soft.ts does after a generation
// (testdata/format.mjs): the unused imports removed (but with keepImports),
// then prettier with the soft.ts options and the print width of the fixture;
// lenient leaves a file that does not parse as it is (the output of v1).
func formatDir(t *testing.T, f fixture, dir string, keepImports, lenient bool) {
	t.Helper()
	tools := os.Getenv(toolsEnv)
	width := "120"
	if w, ok := f.Props["printWidth"]; ok {
		width = w
	}
	script, _ := filepath.Abs("testdata/format.mjs")
	args := []string{script, tools, width, dir}
	if keepImports {
		args = append(args, "--keep-imports")
	}
	if lenient {
		args = append(args, "--lenient")
	}
	if output, err := exec.Command("node", args...).CombinedOutput(); err != nil {
		t.Fatalf("format %s: %v\n%s", dir, err, output)
	}
}

// requireTools skips the test without node or the formatting tools.
func requireTools(t *testing.T) {
	t.Helper()
	if os.Getenv(toolsEnv) == "" {
		t.Skipf("set %s (a directory resolving prettier and oxlint, such as soft.ts/ecore) to format TypeScript", toolsEnv)
	}
	if _, err := exec.LookPath("node"); err != nil {
		t.Skip("node not found")
	}
}

// TestV1 compares the v1 generator with the expected files of every case: the
// docker image named by SOFT_GEN_V1_TS_IMAGE generates the case, its header
// line is the v2 one, then its files and a copy of the expected ones are
// formatted as soft.ts does; every file must equal its expected file, but the
// V1Differences of the case.
func TestV1(t *testing.T) {
	if os.Getenv("SOFT_GEN_V1_TS_IMAGE") != "" {
		requireTools(t)
	}
	suite.TestV1(t, goldentest.V1{
		ImageEnv: "SOFT_GEN_V1_TS_IMAGE",
		Image:    "masagroup/soft.generator.ts:v1.7.0",
		File: func(_ string, content []byte) ([]byte, error) {
			return bytes.Replace(content, []byte(v1Header), []byte(v2Header), 1), nil
		},
		Dir: func(t *testing.T, f goldentest.Fixture, dir string) { formatDir(t, f, dir, false, true) },
	})
}

// prettierExceptions lists the expected files prettier would change, with
// the reason: the layout the generator writes is the one prettier gives the
// code, but for these lines.
var prettierExceptions = map[string]string{}

// TestPrettier checks that the expected files are formatted as prettier
// formats them: prettier with the soft.ts options rewrites none of them, but
// the prettierExceptions.
func TestPrettier(t *testing.T) {
	requireTools(t)
	for _, f := range suite.Fixtures() {
		t.Run(f.Name, func(t *testing.T) {
			formatted := t.TempDir()
			if err := os.CopyFS(formatted, os.DirFS(suite.ExpectedDir(f))); err != nil {
				t.Fatal(err)
			}
			formatDir(t, f, formatted, true, false)
			files, err := goldentest.ListFiles(formatted)
			if err != nil {
				t.Fatal(err)
			}
			for _, file := range files {
				if _, ok := prettierExceptions[f.Name+"/"+file]; ok {
					continue
				}
				want, _ := os.ReadFile(filepath.Join(suite.ExpectedDir(f), filepath.FromSlash(file)))
				got, _ := os.ReadFile(filepath.Join(formatted, filepath.FromSlash(file)))
				want = bytes.ReplaceAll(want, []byte("\r\n"), []byte("\n"))
				if !bytes.Equal(want, got) {
					t.Errorf("%s: prettier changes it:\n%s", file, writer.UnifiedDiff(file, want, got))
				}
			}
		})
	}
}
